insert into public.platform_modules(key,name,description,icon,app_url,monthly_price_cents,display_order,is_active,publisher_name,publisher_type,marketplace_category,visibility,install_mode,commission_bps,current_version,manifest,is_marketplace_listed,updated_at)
values('workspace','Workspace','Unified ApplianceIQ organization, location, app, notification, and cross-module context shell.','◫','/workspace.html',0,0,true,'Appliance IQ','first_party','Platform','private','first_party',0,'2.0.0',jsonb_build_object('registry_key','applianceiq-platform','surface','workspace','phase',2),false,now())
